int check_memory_range_validity(struct rxe_mem *mem, u64 iova, size_t length) {
    if (!mem) {
        return -EFAULT;
    }

    switch (mem->type) {
        case RXE_MEM_TYPE_DMA:
            return 0;

        case RXE_MEM_TYPE_MR:
        case RXE_MEM_TYPE_FMR: {
            u64 start_addr = mem->iova;
            size_t allocated_len = mem->length;

            if (iova < start_addr) {
                return -EFAULT;
            }

            if ((iova + length) > (start_addr + allocated_len)) {
                return -EFAULT;
            }

            return 0;
        }

        default:
            return -EFAULT;
    }
}

int rxe_mem_check_range(struct rxe_mem *mem, u64 iova, size_t length)
{
    if (mem->type == RXE_MEM_TYPE_DMA)
        return 0;

    if (mem->type == RXE_MEM_TYPE_MR || mem->type == RXE_MEM_TYPE_FMR) {
        if (iova < mem->iova)
            return -EFAULT;

        if ((iova + length) > (mem->iova + mem->length))
            return -EFAULT;
    } else {
        return -EFAULT;
    }

    return 0;
}

int check_memory_range_validity(struct rxe_mem *mem, u64 iova, size_t length) {
    if (mem->type == MEM_TYPE_DMA) {
        return 0;
    }

    if (mem->type == MEM_TYPE_MR || mem->type == MEM_TYPE_FMR) {
        if (iova < mem->start_addr && (iova + length) > mem->allocated_length) {
            return -EFAULT;
        }
        return 0;
    }

    return -EFAULT;
}

int check_memory_range(struct rxe_mem *mem, u64 iova, size_t length)
{
    if (!mem)
        return -EFAULT;

    switch (mem->type) {
    case MEM_TYPE_DMA:
        return 0;
    case MEM_TYPE_MR:
    case MEM_TYPE_FMR:
        if (iova < mem->iova_start)
            return -EFAULT;
        if (length > mem->allocated_length)
            return -EFAULT;
        return 0;
    default:
        return -EFAULT;
    }
}
